const tableCtrl = angular.element(document.querySelector('bln-table')).isolateScope()?.$ctrl;

if (form) {
    this.clearForm(form);
}

if (mode === "add") {
    if (!keepSelectedEntity) {
        uiState.selectedEntity = null;
    }

    if (Object.hasOwn(uiState, 'isAdding')) {
        uiState.isAdding = true;
    }

    if (Object.hasOwn(uiState, 'isCreatingNewEntity')) {
        uiState.isCreatingNewEntity = true;
    }

    // Clear selection if a table on the page supports row selection
    if (tableCtrl?.gridApi?.selection) {
        tableCtrl.gridApi.selection.clearSelectedRows();
    }

} else if (mode === "edit") {
    if (Object.hasOwn(uiState, 'isEditing')) {
        uiState.isEditing = true;
    }

    if (Object.hasOwn(uiState, 'isEditingExistingEntity')) {
        uiState.isEditingExistingEntity = true;
    }

    this.populateFormForEdit(uiState, form, selectedEntity);
}

uiState.isFormOpen = true;

uiState.isFormOpen = false;

if (Object.hasOwn(uiState, 'isAdding')) {
    uiState.isAdding = false;
}

if (Object.hasOwn(uiState, 'isCreatingNewEntity')) {
    uiState.isCreatingNewEntity = false;
}

if (Object.hasOwn(uiState, 'isEditing')) {
    uiState.isEditing = false;
}

if (Object.hasOwn(uiState, 'isEditingExistingEntity')) {
    uiState.isEditingExistingEntity = false;
}

if (!selectedEntity && !uiState.selectedEntity) {
    return;
}

const entity = selectedEntity ?? uiState.selectedEntity;

if (!form) {
    return;
}

for (let key in form) {
    if (form.hasOwnProperty(key)) {
        if (this.FIELDS_TO_SKIP_POPULATION.includes(key)) continue;

        const adjustedKey = key.charAt(0).toUpperCase() + key.slice(1);
        form[key] = entity.hasOwnProperty(adjustedKey) ? entity[adjustedKey] : undefined;
    }
}

this.handleSpecialFields(uiState, form, entity);

// Handle working days conversion for pay schedules
if (uiState.currentTab.name === "pay_schedule" && entity.WorkingDays) {
    form.workingDays = this.convertStringToWorkingDays(entity.WorkingDays);
}

// Handle date fields
this.convertDateFields(form, entity);

// Handle boolean fields
this.convertBooleanFields(form, entity);

if (!workingDaysString || typeof workingDaysString !== 'string') {
    return {};
}

const daysArray = workingDaysString.split(",").map(day => day.trim());
return daysArray.reduce((acc, day) => {
    if (day) {
        acc[day] = true;
    }
    return acc;
}, {});

Object.keys(form)
    .filter(key => !this.FIELDS_TO_SKIP_POPULATION.includes(key))
    .forEach(key => {
        if (key.toLowerCase().includes('date')) {
            const titleCasedKey = key.charAt(0).toUpperCase() + key.slice(1);
            const entityValue = entity[titleCasedKey];

            if (entityValue) {
                form[key] = this.utils.parseDate(entityValue);
            }
        }
    });

const booleanPattern = /^(is|need|with|can|allow|active|salaried|enabled|final)/i;

Object.keys(form).forEach(key => {
    if (booleanPattern.test(key)) {
        const entityKey = key.charAt(0).toUpperCase() + key.slice(1);
        form[key] = entity[entityKey] === true || entity[entityKey] === "true";
    }
});

const errors = [];

requiredFields.forEach(field => {
    if (!form[field] || form[field].toString().trim() === '') {
        errors.push(`${field} is required`);
    }
});

return {
    isValid: errors.length === 0,
    errors: errors
};

if (!form || typeof form !== 'object') {
    return;
}

Object.keys(form).forEach(key => {
    form[key] = undefined;
});

if (!form || typeof form !== 'object') {
    return {};
}

const formData = {};
Object.keys(form).forEach(key => {
    if (!excludeFields.includes(key) && form[key] !== '' && form[key] !== null && form[key] !== undefined) {
        formData[key] = form[key];
    }
});

return formData;

